+function findDependentOptionTerm(usage: Usage): Extract<UsageTerm, {
+  readonly type: "option";
+}> | undefined {
+  for (const term of usage) {
+    if (term.type === "option" && term.dependsOn !== undefined) return term;
+    if (term.type === "optional" || term.type === "multiple") {
+      const found = findDependentOptionTerm(term.terms);
+      if (found !== undefined) return found;
+    } else if (term.type === "exclusive") {
+      for (const terms of term.terms) {
+        const found = findDependentOptionTerm(terms);
+        if (found !== undefined) return found;
+      }
+    }
+  }
+  return undefined;
+}
+
+function valueFromOptionState(state: unknown): unknown {
+  if (Array.isArray(state)) return valueFromOptionState(state[0]);
+  if (state !== null && typeof state === "object") {
+    const record = state as Record<string, unknown>;
+    if (record.success === true) return record.value;
+    if (record.result !== null && typeof record.result === "object") {
+      return valueFromOptionState(record.result);
+    }
+    if (record.preliminaryResult !== null &&
+      typeof record.preliminaryResult === "object") {
+      return valueFromOptionState(record.preliminaryResult);
+    }
+  }
+  return undefined;
+}
+
+function wasOptionExplicitlyProvided(
+  state: unknown,
+  term: Extract<UsageTerm, { readonly type: "option" }> | undefined,
+): boolean {
+  if (Array.isArray(state)) return state.length > 0;
+  if (state === null || typeof state !== "object") return false;
+  const record = state as Record<string, unknown>;
+  if (record.success !== true) return false;
+  // A valueless option initializes to `{ success: true, value: false }`.
+  return term?.metavar !== undefined || record.value !== false;
+}
+
+interface DependencyEvaluation {
+  readonly satisfied: boolean;
+  readonly explicitlyFalsy: boolean;
+  readonly failedCondition: { readonly condition: string; readonly value?: unknown } | undefined;
+}
+
+function evaluateOptionDependency(
+  dependency: OptionDependency,
+  states: Readonly<Record<string | symbol, unknown>>,
+  optionTerms: ReadonlyMap<string | symbol, Extract<UsageTerm, {
+    readonly type: "option";
+  }>>,
+  optionKeys: ReadonlyMap<string, string | symbol>,
+): DependencyEvaluation {
+  const conditions = dependency.anyOf ?? dependency.allOf ??
+    (dependency.option === undefined ? [] : [dependency]);
+  const useAnyOf = dependency.anyOf !== undefined;
+  const results = conditions.map((condition) => {
+    const key = optionKeys.get(condition.option);
+    const state = key === undefined ? undefined : states[key];
+    const optionTerm = key === undefined ? undefined : optionTerms.get(key);
+    const value = valueFromOptionState(state);
+    const satisfied = key !== undefined &&
+      (Object.hasOwn(condition, "value") ? value === condition.value : Boolean(value));
+    return {
+      satisfied,
+      explicitlyFalsy: key !== undefined &&
+        wasOptionExplicitlyProvided(state, optionTerm) && !Boolean(value),
+      condition,
+    };
+  });
+  const satisfied = useAnyOf
+    ? results.some((result) => result.satisfied)
+    : results.every((result) => result.satisfied);
+  const failed = results.find((result) => !result.satisfied);
+  return {
+    satisfied,
+    explicitlyFalsy: results.some((result) => result.explicitlyFalsy),
+    failedCondition: failed === undefined ? undefined : failed.condition,
+  };
+}
